-- Enrich Course 2 Lesson 3 with source-attested Standard Kurmanji gender, number and ezafe forms.
-- Haig & Öpengin (2018), pp. 171-172 and Table 8, pp. 178-179.
DO $migration$
DECLARE affected integer;
BEGIN
  UPDATE public.lesson_content
  SET content_html = $new$<section class="klesson-card"><h2>١. ڕەگەزی ڕێزمانی لە ناوەکاندا</h2><p>لە کورمانجیی ستاندارددا ناوە تاکەکان دوو ڕەگەزی ڕێزمانییان هەیە: نێر و مێ. ئەم ڕەگەزە تایبەتمەندیی ڕێزمانیی ناوە، نەک هەمیشە نیشاندەری ڕەگەزی سروشتی. لە ناوی مرۆڤ و ئاژەڵی دیاردا هەندێک جار واتای سروشتی کاریگەرە؛ بەڵام بۆ زۆر ناوی شتەکان دیاریکردنی ڕەگەز پێویستی بە فێربوونی فۆڕمی وشە و بەکارهێنانی ستاندارد هەیە.</p></section>
<section class="klesson-card"><h2>٢. ڕەگەز لە فۆڕمی ئەزافەدا</h2><p>ئەزافە لە کورمانجیی ستاندارددا لەگەڵ ناوی سەرەکی ڕێکدەکەوێت. لە نموونەی ناوی دیاردا، نێر و مێ فۆڕمی جیاوازی ئەزافەیان هەیە:</p><table><thead><tr><th>ناو</th><th>فۆڕمی ئەزافە</th><th>واتا</th></tr></thead><tbody><tr><td><code>gund-ê</code></td><td>نێری تاک</td><td>ئەزافەی نێر</td></tr><tr><td><code>jin-a</code></td><td>مێی تاک</td><td>ئەزافەی مێ</td></tr><tr><td><code>mal-a me</code></td><td>مێی تاک + خاوەندار</td><td>ماڵی ئێمە</td></tr></tbody></table><p>Haig و Öpengin (2018، لاپەڕەی ١٧٨) نموونەی <code>bajar-ek-î mezin</code> «شارێکی گەورە» و <code>mal-a me</code> «ماڵی ئێمە» دەهێننەوە. هاوەڵناو لە پێکهاتەی ئەزافەدا بە ناوەکەوە دەبەسترێتەوە و فۆڕمی ئەزافە بە ڕەگەزی ناوی سەرەکی پەیوەستە.</p></section>
<section class="klesson-card"><h2>٣. ژمارە: تاک و کۆ</h2><p>لە فۆڕمی ئەزافەدا، جیاوازیی ژمارەش دەردەکەوێت. لە ستانداردی کورمانجی، فۆڕمی باوی ئەزافەی کۆ <code>-ên</code>ە و بۆ ناوی نێر و مێ بەکاردێت:</p><table><thead><tr><th>فۆڕم</th><th>ژمارە/ڕەگەز</th><th>تێبینی</th></tr></thead><tbody><tr><td><code>gund-ê</code></td><td>نێری تاک</td><td>ئەزافەی تاک</td></tr><tr><td><code>jin-a</code></td><td>مێی تاک</td><td>ئەزافەی تاک</td></tr><tr><td><code>gund-ên</code></td><td>کۆ</td><td>ئەزافەی کۆ</td></tr><tr><td><code>jin-ên</code></td><td>کۆ</td><td>ئەزافەی کۆ</td></tr></tbody></table><p>لە کۆدا جیاوازیی ڕەگەزی نێر و مێ لە فۆڕمی ئەزافەدا لادەچێت؛ فۆڕمی کۆ بۆ هەردوو ڕەگەز هاوبەشە. فۆڕمی <code>-êt</code> لە هەندێک ناوچە، بە تایبەتی بادینی، زیاتر دەبینرێت؛ لەم وانەیەدا <code>-ên</code> وەک فۆڕمی ستانداردی بنەڕەتی پیشان دەدرێت.</p></section>
<section class="klesson-card"><h2>٤. نادیاری و سنووری یاساکە</h2><p>لە ناوی نادیاریی تاکدا، <code>-ek</code> لەگەڵ ئەزافەدا دەتوانێت فۆڕمی وەک <code>gundek-î</code> (نێر) و <code>jinek-e</code> (مێ) دروست بکات. بەڵام سەرچاوەکان ئاگادار دەکەنەوە کە جیاوازیی ڕەگەز لە ئەزافەی دوای <code>-ek</code>دا لە هەندێک شێوەزار و بەکارهێناندا لاواز دەبێت و فۆڕمەکان تێکەڵ دەبن؛ بۆیە ئەم دوو فۆڕمە وەک نموونەی ستاندارد فێربە، نەک یاسایەکی بێ‌جیاوازی بۆ هەموو ناوچەکان.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">لە ستانداردی کورمانجی، ڕەگەزی ناو لە تاکدا جیاوازە؛ لە کۆدا ئەم جیاوازییە لە ئەزافەدا لادەچێت. فۆڕمی <code>-êt</code> بە گشتی بە فۆڕمی سەرەکیی ستاندارد مەگرە؛ Haig و Öpengin دەڵێن ئەم فۆڕمە بە تایبەتی لە بادینی باوترە. هەروەها لە ناوی نادیاریی <code>-ek</code>دا ڕێککەوتنی ڕەگەز لە هەندێک بەکارهێناندا نائاسایی و نایەکسانە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>لە کورمانجیی ستاندارددا ناوی تاک چەند ڕەگەزی ڕێزمانی هەیە؟</li><li>لە <code>gund-ê</code> و <code>jin-a</code>دا کام فۆڕم نێرە و کام مێیە؟</li><li>فۆڕمی باوی ئەزافەی کۆ چییە و ئایا لە نێر و مێدا جیاوازە؟</li><li>بۆچی نابێت یاسای ڕەگەزی ئەزافەی دوای <code>-ek</code> بە بێ جیاوازی بۆ هەموو شێوەزارەکان بگشتێنین؟</li></ol></section>
<section class="klesson-card"><h2>وەڵامی نموونەیی</h2><ol><li>دوو ڕەگەزی ڕێزمانی هەیە: نێر و مێ.</li><li><code>gund-ê</code> ئەزافەی نێری تاکە؛ <code>jin-a</code> ئەزافەی مێی تاکە.</li><li>فۆڕمی باوی کۆ <code>-ên</code>ە و بۆ هەردوو ڕەگەز بەکاردێت.</li><li>چونکە سەرچاوەکان تێکەڵبوونی فۆڕمەکانی ئەزافەی دوای <code>-ek</code> و جیاوازیی ناوچەیی تۆمار دەکەن.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey & Ergin Öpengin. (2018). “Kurmanji Kurdish in Turkey: Structure, varieties and status.” pp. 156–214. Table 8, pp. 178–179: Standard Kurmanji ezafe forms; pp. 171–172: grammatical gender and dialect variation. <a href="https://www.uni-bamberg.de/fileadmin/aspra/06_Team/Publications_and_CV/HaigOepengin2018_Kurmanji_Kurdish_.pdf" target="_blank" rel="noopener">PDF — University of Bamberg</a>.</li><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">ئەم خشتە و نموونانە بۆ کورمانجیی ستانداردن؛ فۆڕمەکانی بادینی و شێوەزارەکانی دیکە بە جیاوازی دیاری کراون.</p></section>$new$,
      updated_at = now()
  WHERE lesson_key = 'kurmanji-course-2-lesson-03.html'
    AND course_id = 'kurmanji-course-2'
    AND content_html = $old$<section class="klesson-card"><h2>١. ڕەگەزی ڕێزمانی</h2><p>لە کورمانجیی ستاندارددا جیاوازی نێر و مێ لە ناوی تاکدا هەیە. ڕەگەزی ڕێزمانی هەمیشە بە واتای سروشتیی نێر و مێ یەکسان نیە؛ پەیویستە ڕەگەزی هەر ناوێک لە سەرچاوەی ڕێزمانی و لە ڕێککەوتنەکانی دەوروبەریدا بپشکنرێت.</p></section><section class="klesson-card"><h2>٢. تاک و کۆ</h2><p>ژمارە جیاوازی نێوان تاک و کۆ نیشان دەدات. لە کورمانجی‌دا شێوەکانی کۆ بە جۆری ناو و فۆڕمی ڕێزمانی پەیوەستن؛ بۆیە نابێت یاسایەکی تاک بۆ هەمو ناوەکان بگشتێندرێت.</p></section><section class="klesson-card"><h2>٣. پەیوەندی بە ڕێککەوتنەوە</h2><p>ڕەگەز و ژمارە لە پاشگری ئەزافەدا ڕەنگ دەدەنەوە. لە زۆر پێکهاتەی ناوی‌دا، فۆڕمی ئەزافە بە ڕەگەز و ژمارەی ناوی سەرەکی پەیوەستە، نەک تەنیا بە وشەی دواتر.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">لە شێوەزارەکانی کورمانجی‌دا جیاوازییەکانی ڕەگەز، ژمارە و فۆڕمی ناو هەن. خشتەی یاساکان دەبێت بە دیاریکردنی شێوەزار و سەرچاوە پێشکەش بکرێت.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ڕەگەزی ڕێزمانی چیە؟</li><li>ئایا ڕەگەزی ڕێزمانی هەمیشە ڕەگەزی سروشتی نیشان دەدات؟</li><li>ڕەگەز و ژمارە چ پەیوەندییەکیان بە ئەزافەوە هەیە؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>$old$;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Expected exactly one unchanged Course 2 Lesson 3 row; updated % rows', affected;
  END IF;
END
$migration$;
